SELECT cr.cr_order_number, cc.cc_name, CASE WHEN cr.cr_return_quantity > 2 THEN 'Large Return' WHEN cr.cr_return_quantity = 42 THEN 'Exact Return' ELSE 'Small Return' END AS return_size_category, (cr.cr_return_amount - cr.cr_return_tax) * 1329.50 AS net_return_amount_scaled, cr.cr_return_amount + cr.cr_fee - cr.cr_return_ship_cost AS adjusted_return_amount, cc.cc_gmt_offset + -5.00 AS gmt_offset_adjusted, (cr.cr_return_quantity * cr.cr_return_amount) / NULLIF(cr.cr_return_quantity, 0) AS avg_return_per_item, CASE WHEN cc.cc_country = 'United States' THEN 'Domestic' ELSE 'International' END AS market_type FROM catalog_returns cr JOIN call_center cc ON cr.cr_call_center_sk = cc.cc_call_center_sk WHERE cr.cr_returned_date_sk BETWEEN 2450966 AND 2450943 AND cc.cc_state = 'NM'
